Размер сегмента (высота, отступы, шрифт) задаёт  `size`  на  `SegmentItem` .
 `size`  на  `SegmentGroup`  меняет только скругление контейнера и отступы стрелок прокрутки.
Передавайте одинаковый  `size`  в группу и в элементы. Доступные размеры:  `xs` ,  `s` . ```tsx
import React from 'react';
import { SegmentGroup, SegmentItem, SegmentProvider } from '@salutejs/sdds-finai';

export function App() {
    const sizes = ['xs', 's'];

    return (
        <div style={{ display: "flex", flexDirection: "column", gap: "1.5rem" }}>
            {sizes.map((size) => (
                <SegmentProvider key={size} defaultSelected={[`${size}_1`]}>
                    <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
                        <div style={{ width: "5rem" }}>size="{size}"</div>
                        <SegmentGroup hasBackground pilled clip={false} size={size}>
                            <SegmentItem label="Label 1" value={`${size}_1`} view="secondary" pilled size={size} />
                            <SegmentItem label="Label 2" value={`${size}_2`} view="secondary" pilled size={size} />
                        </SegmentGroup>
                    </div>
                </SegmentProvider>
            ))}
        </div>
    );
}
```

### Обязательный активный SegmentItem Обязательный активный SegmentItem С помощью свойства  `singleSelectedRequired`  задается поведение,
при котором один сегмент должен быть активным. ```tsx
import React from 'react';
import { SegmentGroup, SegmentItem, SegmentProvider, useSegment } from '@salutejs/sdds-finai';

export function App() {
    const items = Array(4).fill(0);

    const SegmentTemplate = () => {
        const {selectedSegmentItems} = useSegment();

        return (
            <>
                <div>Выбранный элемент: {selectedSegmentItems.join(', ')}</div>
                <br />
                <SegmentGroup hasBackground pilled clip={false}>
                    {items.map((_, i) => (
                        <SegmentItem
                            label={`Label ${i}`}
                            value={`label_${i}`}
                            key={`label_${i}`}
                            view='default'
                            pilled
                        />
                    ))}
                </SegmentGroup>
            </>
        )
    }

    return (
        <div style={{ display: "block" }} >
            <SegmentProvider defaultSelected={['label_1']} singleSelectedRequired>
                <SegmentTemplate/>
            </SegmentProvider>
        </div>
    );
}
```

### Сегменты только с иконкой Сегменты только с иконкой Для отображения сегментов с только иконкой, необходимо использовать  `SegmentIconItem` ```tsx
import React from 'react';
import { IconPlasma } from '@salutejs/plasma-icons'
import { SegmentGroup, SegmentIconItem, SegmentProvider, useSegment } from '@salutejs/sdds-finai';

export function App() {
    const items = Array(4).fill(0);

    const SegmentTemplate = () => {
        const {selectedSegmentItems} = useSegment();

        return (
            <>
                <div>Выбранный элемент: {selectedSegmentItems.join(', ')}</div>
                <br />
                <SegmentGroup hasBackground pilled clip={false}>
                    {items.map((_, i) => (
                        <SegmentIconItem
                            icon={<IconPlasma color="inherit" size="xs" />}
                            value={`label_${i}`}
                            key={`label_${i}`}
                            view='default'
                        />
                    ))}
                </SegmentGroup>
            </>
        )
    }

    return (
        <div style={{ display: "block" }} >
            <SegmentProvider defaultSelected={['label_1']}>
                <SegmentTemplate/>
            </SegmentProvider>
        </div>
    );
}
```

